import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c5_out_act_k10.npy'),dtype=torch.float32); b=-13.6653
torch.manual_seed(3); N=6144
xi=torch.randn(N,2); c=torch.rand(N)
def run(push=None,lo=4,hi=10,thr=0.):
    x=xi.clone(); acts=[]
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,A=net.velocity(x,t,c,("out_act",))
        s=A['out_act']@w+b; acts.append(s)
        if push is not None and lo<=k<hi:
            v=v+(s>thr).float()[:,None]*push
        x=x-v/20
    return x, torch.stack(acts)
